<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_role(['Super Admin']);
$user=current_user();
if(isset($_GET['export'])&&$_GET['export']==='csv'){
 header('Content-Type:text/csv');header('Content-Disposition:attachment; filename="clearx_clearance_report.csv"');
 $out=fopen('php://output','w');fputcsv($out,['Student','USN','Semester','Status','Submitted']);
 $rows=$pdo->query('SELECT u.name,s.usn,cr.semester,cr.status,cr.submitted_at FROM clearance_requests cr JOIN students s ON s.id=cr.student_id JOIN users u ON u.id=s.user_id')->fetchAll();
 foreach($rows as $r)fputcsv($out,$r);exit;
}
$total=$pdo->query('SELECT COUNT(*) FROM clearance_requests')->fetchColumn();$approved=$pdo->query("SELECT COUNT(*) FROM clearance_requests WHERE status='Approved'")->fetchColumn();$pending=$pdo->query("SELECT COUNT(*) FROM clearance_requests WHERE status IN ('Pending','Partially Approved')")->fetchColumn();$rejected=$pdo->query("SELECT COUNT(*) FROM clearance_requests WHERE status='Rejected'")->fetchColumn();
$departments=$pdo->query('SELECT d.name,COUNT(dc.id) total,SUM(dc.status="Approved") approved FROM departments d LEFT JOIN department_clearances dc ON dc.department_id=d.id GROUP BY d.id,d.name')->fetchAll();
$pageTitle='Reports | CLEARX';require_once __DIR__.'/../includes/header.php';
?><div class="app-layout"><?php require_once __DIR__.'/../includes/sidebar.php';?><main class="app-main"><header class="topbar"><button class="menu-toggle"><i class="fa-solid fa-bars"></i></button><div class="topbar-user"><b><?=e($user['name'])?></b><span>Super Admin</span></div><div class="avatar">SA</div></header><div class="content"><div class="page-header"><div><p>ANALYTICS</p><h1>Reports & Statistics</h1></div><a class="btn btn-primary" href="reports.php?export=csv"><i class="fa-solid fa-download"></i> Export CSV</a></div><div class="cards"><div class="card metric"><div class="metric-head"><span>Total Requests</span><div class="metric-icon"><i class="fa-solid fa-file-lines"></i></div></div><h2><?=e($total)?></h2></div><div class="card metric"><div class="metric-head"><span>Approved</span><div class="metric-icon"><i class="fa-solid fa-circle-check"></i></div></div><h2><?=e($approved)?></h2></div><div class="card metric"><div class="metric-head"><span>Pending</span><div class="metric-icon"><i class="fa-solid fa-hourglass-half"></i></div></div><h2><?=e($pending)?></h2></div><div class="card metric"><div class="metric-head"><span>Rejected</span><div class="metric-icon"><i class="fa-solid fa-circle-xmark"></i></div></div><h2><?=e($rejected)?></h2></div></div><section class="panel"><div class="panel-header"><h2>Department Clearance Percentage</h2></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Department</th><th>Processed</th><th>Approved</th><th>Percentage</th></tr></thead><tbody><?php foreach($departments as $d):$pct=$d['total']?round((int)$d['approved']*100/(int)$d['total']):0?><tr><td><?=e($d['name'])?></td><td><?=e($d['total'])?></td><td><?=e($d['approved'])?></td><td><div class="progress-row"><div class="progress-bar"><span style="width:<?=$pct?>%"></span></div><b><?=$pct?>%</b></div></td></tr><?php endforeach;?></tbody></table></div></section></div><?php require_once __DIR__.'/../includes/footer.php';?></main></div>
